result = []
tag_path = ''
try:
	tag_path = str(value.get('tagPath') or '')
except:
	pass
if not tag_path:
	return result
try:
	rows = system.tag.browse(path=tag_path, filter={'recursive': True}).getResults()
except:
	return result
candidates = []
for t in rows:
	try:
		if str(t['tagType']) != 'AtomicTag':
			continue
		candidates.append(str(t['fullPath']))
	except:
		pass
if not candidates:
	return result
try:
	ae = system.tag.readBlocking([p + '.AlarmEvalEnabled' for p in candidates])
except:
	return result
for path, a in zip(candidates, ae):
	try:
		if a.value == True:
			result.append(path)
	except:
		pass
return result

tags = value.get('tags') or []
if not tags:
	return 'No alarmed tags found under this device.'
lines = []
for t in tags:
	path = str(t)
	parts = [p for p in path.replace('\\', '/').split('/') if p]
	if len(parts) >= 2:
		alias = parts[-2] + '/' + parts[-1]
	elif parts:
		alias = parts[-1]
	else:
		alias = path
	if ']' in alias:
		alias = alias.split(']', 1)[-1]
	lines.append(alias)
return '\n'.join(lines)

